package cn.mint.tv;
import org.junit.*;import org.junit.rules.TemporaryFolder;import static org.junit.Assert.*;import java.io.*;import java.nio.file.*;import java.util.*;import org.json.*;
public class StateDiskTest {
 @Rule public TemporaryFolder tmp=new TemporaryFolder();
 static String read(Path p)throws IOException{return new String(Files.readAllBytes(p),java.nio.charset.StandardCharsets.UTF_8);}
 static void write(Path p,String s)throws IOException{Files.write(p,s.getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 Map<String,Map<String,Object>> bucket(String name,String key,Object value){Map<String,Object> values=new HashMap<>();values.put(key,value);Map<String,Map<String,Object>> out=new HashMap<>();out.put(name,values);return out;}
 @Test public void roundtripTypesAndUnicode()throws Exception{File dir=tmp.newFolder();StateDisk disk=new StateDisk(dir);Map<String,Object> values=new HashMap<>();values.put("favorites",new HashSet<>(Arrays.asList("央视","福建")));values.put("long",1700000000000L);values.put("flag",true);values.put("text","中文频道\nhttps://example.com");Map<String,Map<String,Object>> b=new HashMap<>();b.put("settings",values);disk.commit(b);Map<String,Object> read=new StateDisk(dir).load();assertEquals(values,read);}
 @Test public void progressDoesNotRewriteLargeLists()throws Exception{File dir=tmp.newFolder();StateDisk disk=new StateDisk(dir);disk.commit(bucket("lists","base","source data"));String first=read(new File(dir,"index.json").toPath());String listFile=new JSONObject(first).getString("lists");disk.commit(bucket("scan-progress","healthUrl",2));assertEquals(listFile,new JSONObject(read(new File(dir,"index.json").toPath())).getString("lists"));assertEquals("source data",new StateDisk(dir).load().get("base"));}
 @Test public void interruptedCommitRollsBackWholeGeneration()throws Exception{File dir=tmp.newFolder();StateDisk disk=new StateDisk(dir);disk.commit(bucket("settings","value","old"));String old=read(new File(dir,"index.json").toPath());disk.commit(bucket("settings","value","new"));write(new File(dir,"index.bak").toPath(),old); // Keep an old bucket to model crash before garbage collection.
 String oldFile=new JSONObject(old).getString("settings");write(new File(dir,oldFile).toPath(),"{\"value\":\"old\"}");assertEquals("old",new StateDisk(dir).load().get("value"));}
 @Test public void failedWriteLeavesPreviousSnapshot()throws Exception{File dir=tmp.newFolder();StateDisk disk=new StateDisk(dir);disk.commit(bucket("settings","value","old"));assertTrue(new File(dir,"index.new").mkdir());try{disk.commit(bucket("settings","value","new"));fail();}catch(IOException expected){}assertEquals("old",new StateDisk(dir).load().get("value"));}
 @Test public void emptyBucketRemovesItsValues()throws Exception{File dir=tmp.newFolder();StateDisk d=new StateDisk(dir);d.commit(bucket("settings","x",1));Map<String,Map<String,Object>> b=new HashMap<>();b.put("settings",new HashMap<>());d.commit(b);assertFalse(new StateDisk(dir).load().containsKey("x"));}
 @Test public void corruptIndexFailsWithoutOverwriting()throws Exception{File dir=tmp.newFolder();File index=new File(dir,"index.json");write(index.toPath(),"broken");try{new StateDisk(dir);fail();}catch(JSONException expected){}assertEquals("broken",read(index.toPath()));}
 @Test public void missingBucketFailsWithoutResettingData()throws Exception{File dir=tmp.newFolder();File index=new File(dir,"index.json");write(index.toPath(),"{\"settings\":\"missing.json\"}");try{new StateDisk(dir).load();fail();}catch(IOException expected){}assertTrue(index.exists());}
}
